## Paso 1: Clase Abstracta para Productos

::: {#90674a41 .cell execution_count=1}
``` {.python .cell-code}
from abc import ABC, abstractmethod
from datetime import datetime, timedelta
import random

class Producto(ABC):
    """Clase abstracta base para todos los productos"""

    contador_id = 1000

    def __init__(self, nombre, precio, stock):
        Producto.contador_id += 1
        self.__id = Producto.contador_id
        self.__nombre = nombre
        self.__precio = precio
        self.__stock = stock

    # Propiedades con getters y setters
    @property
    def id(self):
        return self.__id

    @property
    def nombre(self):
        return self.__nombre

    @property
    def precio(self):
        return self.__precio

    @precio.setter
    def precio(self, valor):
        if valor > 0:
            self.__precio = valor
        else:
            raise ValueError("El precio debe ser positivo")

    @property
    def stock(self):
        return self.__stock

    def reducir_stock(self, cantidad):
        if cantidad <= self.__stock:
            self.__stock -= cantidad
            return True
        return False

    def aumentar_stock(self, cantidad):
        if cantidad > 0:
            self.__stock += cantidad

    # Método abstracto que las subclases deben implementar
    @abstractmethod
    def obtener_descripcion(self):
        pass

    # Método abstracto para calcular precio con descuentos especiales
    @abstractmethod
    def calcular_precio_final(self):
        pass

    # Métodos especiales
    def __str__(self):
        return f"{self.nombre} - ${self.precio}"

    def __repr__(self):
        return f"{self.__class__.__name__}(id={self.id}, nombre='{self.nombre}', precio={self.precio})"

    def __eq__(self, otro):
        return self.id == otro.id

    def __lt__(self, otro):
        return self.precio < otro.precio
```
